pous.declaration:
FUNCTION_BLOCK HeightSort
VAR_INPUT
    height : REAL;
    risingSort : BOOL;
END_VAR
VAR_OUTPUT
    binSel : INT;
    sortPulse : BOOL;
END_VAR
VAR
    prev : BOOL;
    edge : BOOL;
END_VAR

pous.implementation:
edge := risingSort AND NOT prev;
prev := risingSort;
sortPulse := edge;
IF edge THEN
    IF height < 10.0 THEN
        binSel := 1;
    ELSIF height <= 20.0 THEN
        binSel := 2;
    ELSE
        binSel := 3;
    END_IF
END_IF
